$second=$requests->create((int)$a['id'],$friday2);$first=$requests->create((int)$a['id'],$friday);$items=$requests->forUser((int)$a['id'],date('Y-m-d'));
$check(array_column($items,'requestDate')===[$friday,$friday2],'Gesuche chronologisch sortiert.');
$requests->create((int)$c['id'],$friday);$anonymous=$requests->activeForOrganizations([101],null,date('Y-m-d'));$sameDate=array_values(array_filter($anonymous[101],static fn(array $item):bool=>$item['requestDate']===$friday));$check(count($anonymous[101])===3&&count($sameDate)===2&&!isset($anonymous[101][0]['displayName'])&&isset($anonymous[101][0]['requestId'])&&$anonymous[101][0]['canContact'],'Anonyme gebündelte Abfrage liefert alle Gesuche desselben Termins ohne Namensbestandteile und nur mit Kontakt-Referenz.');
$loggedIn=$requests->activeForOrganizations([101],(int)$b['id'],date('Y-m-d'));$check($loggedIn[101][0]['displayName']==='Anna A.'&&$loggedIn[101][0]['canContact']&&isset($loggedIn[101][0]['requestId']),'Eingeloggte gebündelte Abfrage liefert Teilanonymisierung und sichere Referenz.');
$ownView=$requests->activeForOrganizations([101],(int)$a['id'],date('Y-m-d'));$check($ownView[101][0]['isOwn']&&!$ownView[101][0]['canContact']&&!isset($ownView[101][0]['requestId']),'Eigenes Gesuch ist nicht kontaktierbar.');
$duplicate=false;try{$requests->create((int)$a['id'],$friday);}catch(DomainException){$duplicate=true;}$check($duplicate,'Doppeltes Gesuch verhindert.');
$wrong=false;try{$requests->create((int)$a['id'],$wednesday);}catch(InvalidArgumentException){$wrong=true;}$check($wrong,'Falscher Meeting-Wochentag serverseitig abgewiesen.');
$past=false;try{$requests->create((int)$a['id'],'2020-01-01');}catch(InvalidArgumentException){$past=true;}$check($past,'Vergangenes Datum abgewiesen.');
$check(!$requests->deleteForUser($first['id'],(int)$b['id'])&&$requests->deleteForUser($first['id'],(int)$a['id']),'Ownership beim Löschen erzwungen.');
$offers=new RepresentationOfferRepository($pdo);$always=$offers->createMany((int)$b['id'],[101],true,[])[0];$merged=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'),[$friday2]);
$check(count($merged['datedOffers'])===1&&$merged['datedOffers'][0]['date']===$friday2&&$merged['datedOffers'][0]['providers'][0]['offerId']===$always,'Gesuchstermin wird mit Immer-Anbieter zusammengeführt.');
$pdo->exec('DELETE FROM representation_offers');$empty=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'),[$friday2]);$check(count($empty['datedOffers'])===1&&$empty['datedOffers'][0]['providers']===[],'Gesuch bleibt ohne Angebot sichtbar.');
echo "PASS representation requests: Datum, Wochentag, Dublette, Ownership, Sortierung und Angebotszusammenführung\n";
